"""Locate a PUBLIC face dataset on HF and pull N images at >=200px.

The previous attempt hardcoded dataset names and hit 401 (gated). Instead:
enumerate candidates from the HF search API (sorted by downloads), then test
each through the datasets-server rows API, which serves public datasets
without auth. Stop at the first that yields enough usable images.
"""
import sys, os, io, json, urllib.request, urllib.parse

OUT = sys.argv[1]
NEED = int(sys.argv[2])
os.makedirs(OUT, exist_ok=True)

UA = {"Accept": "application/json"}

def get(url, timeout=60):
    return urllib.request.urlopen(urllib.request.Request(url, headers=UA), timeout=timeout).read()

def search(term, limit=40):
    u = ("https://huggingface.co/api/datasets?search=%s&sort=downloads&direction=-1&limit=%d"
         % (urllib.parse.quote(term), limit))
    try:
        return [d["id"] for d in json.loads(get(u))]
    except Exception as e:
        print("search failed", term, type(e).__name__, str(e)[:120], flush=True)
        return []

cands = []
for term in ("ffhq", "celeba-hq", "celeba", "face"):
    for d in search(term):
        if d not in cands:
            cands.append(d)
print("candidates found:", len(cands), flush=True)
print(json.dumps(cands[:60]), flush=True)

# prefer names that look like a plain face-image corpus at decent resolution
def score(name):
    n = name.lower()
    s = 0
    if "ffhq" in n: s -= 100
    if "celeba" in n: s -= 60
    for k, w in (("1024", -20), ("512", -18), ("256", -15), ("128", 5), ("64", 40), ("32", 60)):
        if k in n: s += w
    for bad in ("caption", "text", "mask", "seg", "landmark", "attr", "sketch",
                "cartoon", "anime", "blur", "lr", "sr", "embed", "latent", "clip"):
        if bad in n: s += 30
    return s

cands.sort(key=score)
print("ordered:", json.dumps(cands[:20]), flush=True)

from PIL import Image

def try_ds(ds, minpx):
    q = urllib.parse.quote(ds, safe="")
    try:
        sp = json.loads(get("https://datasets-server.huggingface.co/splits?dataset=" + q))["splits"]
    except Exception as e:
        return 0, "splits:%s" % type(e).__name__
    sp = sorted(sp, key=lambda s: 0 if s["split"] == "train" else 1)[0]
    url = ("https://datasets-server.huggingface.co/rows?dataset=%s&config=%s&split=%s&offset=0&length=%d"
           % (q, urllib.parse.quote(sp["config"], safe=""), urllib.parse.quote(sp["split"], safe=""),
              min(NEED * 2, 100)))
    try:
        rows = json.loads(get(url, 120)).get("rows", [])
    except Exception as e:
        return 0, "rows:%s" % type(e).__name__
    n = 0
    for i, r in enumerate(rows):
        src = None
        for v in r["row"].values():
            if isinstance(v, dict) and "src" in v:
                src = v["src"]; break
        if not src:
            continue
        try:
            data = urllib.request.urlopen(src, timeout=90).read()
            im = Image.open(io.BytesIO(data)).convert("RGB")
        except Exception:
            continue
        if min(im.size) < minpx:
            return 0, "too small %s" % (im.size,)
        im.save(os.path.join(OUT, "face_%03d.png" % i))
        n += 1
        if n >= NEED:
            break
    return n, "ok"

got, used = 0, None
for minpx in (200, 128):
    for ds in cands[:14]:
        n, msg = try_ds(ds, minpx)
        print("  %-45s minpx=%d -> %d (%s)" % (ds, minpx, n, msg), flush=True)
        if n >= NEED:
            got, used = n, ds
            break
    if got:
        break

print("RESULT dataset=%s n=%d minpx_pass=%s" % (used, got, minpx), flush=True)
json.dump({"dataset": used, "n": got}, open(os.path.join(OUT, "_source.json"), "w"))
sys.exit(0 if got >= NEED else 3)
EOF
